class SeqStop(GenericTabContent):
    """Seqstop command class."""

    def __init__(self, connection, seq_id=None, mode="stop", rate=None, prompt=None, newline_chars=None, runner=None):
        """
        Seqstop command.

        :param connection: moler connection to device, terminal when command is executed.
        :param seq_id: Command sequence identifier
        :param mode: Mode of the sequence stopping; already started command will not be aborted in any case
                stop  - Sequence will not start for new UE; currently started sequences will not aborted
                abort - Stop sequence with abort of currently started sequences
                    default = stop
        :param rate: Rate in sequences per second, default=100
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SeqStop, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.seq_id = seq_id
        self.mode = mode
        self.rate = rate
        self.current_ret["All_seq_stopped"] = False
        self.current_ret["Stopped"] = []

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "seq_stop"
        if self.seq_id:
            cmd = f"{cmd} id={self.seq_id}"
        if self.mode:
            cmd = f"{cmd} mode={self.mode}"
        if self.rate:
            cmd = f"{cmd} rate={self.rate}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
                self._parse_stopped(line)
                self._parse_state(line)
            except ParsingDone:
                pass
        return super(SeqStop, self).on_new_line(line, is_full_line)

    # Error: seq_stop: ../src/linux/gate/cmds/invoker/src/command.cpp:355: Missing required argument 'id' (x1)
    _re_error = re.compile(r"(?P<ERROR>(Error:|ERR:).*)")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(SeqStop._re_error, line):
            self.set_exception(CommandFailure(self, f"Error: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    # 16:27:12.487 CSI: UEC-2: Seq-105/UeGr-102: Stopped
    _re_stopped = re.compile(r"(?P<UEC_NR>UEC-.*):.*Seq-(?P<SEQ_ID>.*)/UeGr-(?P<UE_GROUP>.*):.*Stopped")

    def _parse_stopped(self, line):
        if self._regex_helper.search_compiled(SeqStop._re_stopped, line):
            seq_id = self._regex_helper.group("SEQ_ID")
            uec_nr = self._regex_helper.group("UEC_NR")
            ue_group = self._regex_helper.group("UE_GROUP")
            self.current_ret["Stopped"].append({"Id": int(seq_id), "UEC_NR": uec_nr, "UE Group": int(ue_group)})
            raise ParsingDone

    # 16:27:12.566 CSI: SM: ======================== PETSE Sequence Script Complete ========================
    _re_state = re.compile(r".*Script.(?P<STATE>Complete).*")

    def _parse_state(self, line):
        if self._regex_helper.search_compiled(SeqStop._re_state, line):
            self.current_ret["All_seq_stopped"] = True
            raise ParsingDone


